328	// Bar renders a determinate progress bar of the given cell width, coloured as a
329	// red -> amber -> green ramp ACROSS the bar: each filled cell takes the colour
330	// of its own position, so the bar visibly warms as it fills instead of flipping
331	// colour in one step. total <= 0 is indeterminate and renders as an empty
332	// track, because a bar that cannot say how full it is must not imply zero.
333	func (r *Renderer) Bar(done, total, width int) string {
334		if width <= 0 {
335			return ""
336		}
337		full, empty := "#", "."
338		if r != nil && r.caps.Unicode {
339			full, empty = "█", "░"
340		}
341		if total <= 0 {
342			return r.Dim(strings.Repeat(empty, width))
343		}
344		if done < 0 {
345			done = 0
346		}
347		if done > total {
348			done = total
349		}
350		filled := done * width / total
351		// Any real progress must light at least one cell, or a 1/618 export looks
352		// identical to a 0/618 one for the first ninety seconds.
353		if filled == 0 && done > 0 {
354			filled = 1
355		}
356		var b strings.Builder
357		for i := 0; i < filled; i++ {
358			b.WriteString(r.Paint(r.rampColor(float64(i+1)/float64(width)), full))
359		}
360		if rest := width - filled; rest > 0 {
361			b.WriteString(r.Dim(strings.Repeat(empty, rest)))
362		}
363		return b.String()
364	}
