17	// setup_status_output_truth_test.go pins four things a FIRST-TIME user reads on
18	// screen and was misled by: the inner refresh's lines leaking into setup's own
19	// (UX-24), a readiness claim a brain with no index and no baseline cannot back
20	// (UX-25), a status row that named failures without saying why (UX-26), and two
21	// contradictory remedies for one dirty worktree (UX-27).
22	
23	// --- UX-24: the nested refresh is run, not read -----------------------------
24	
25	// TestSetupInstantSubcommandAlwaysDiscardsItsOutput: only --json used to
26	// discard the nested deterministic refresh, so a human first run printed
27	// setup's renderer AND the inner refresh's on top of it -- its own consent
28	// text, its own component names, its own daemon identity.
29	//
30	// Pointing either writer back at a real stream still compiles, and fails here.
31	func TestSetupInstantSubcommandNeverWritesToARealStream(t *testing.T) {
32		t.Parallel()
33		sink := &bytes.Buffer{}
34		sub, captured := newSetupInstantCommand(context.Background(), sink)
35	
36		// stdout goes to the PHASE SINK, not io.Discard as it once did: the nested
37		// reporter has no idea it is nested, and its progress belongs inside the
38		// phase rather than thrown away. The contract that survived the change is
39		// that it never reaches a real stream.
40		if got := sub.OutOrStdout(); got != io.Writer(sink) {
41			t.Fatalf("the nested refresh must write stdout to the phase sink, got %T", got)
42		}
43		if captured == nil {
44			t.Fatal("the nested refresh's stderr must be captured so its warnings can be re-emitted")
45		}
46	
47		// stderr is TEED, so identity cannot be asserted -- and a type check on
48		// io.MultiWriter would pass on a tee to the wrong pair of writers. Assert
49		// the behaviour instead: one write has to land in BOTH places, because
50		// sending it to only one is how either the rendering or the warnings go
51		// missing.
52		const line = "warning: coordinator did not launch\n"
53		if _, err := sub.ErrOrStderr().Write([]byte(line)); err != nil {
54			t.Fatalf("write to the nested stderr: %v", err)
55		}
56		if !strings.Contains(sink.String(), line) {
57			t.Fatalf("the nested refresh's stderr must reach the phase sink, got %q", sink.String())
58		}
59		if !strings.Contains(captured.String(), line) {
60			t.Fatalf("the nested refresh's stderr must reach the capture, got %q", captured.String())
61		}
62		if sub.ErrOrStderr() == io.Writer(os.Stderr) {
63			t.Fatal("the nested refresh must never write to the real stderr")
64		}
65	}
