477	// A Go error is routinely multi-line: errors.Join concatenates its causes with
478	// a newline, and the memory path joins a deterministic failure with a run
479	// failure before it reaches a `warning: %v` line. Keeping only the lines that
480	// carry the prefix dropped every cause after the first — the same information
481	// loss this re-emission exists to repair, one layer down. Raised as a finding
482	// on this PR, and correct.
483	func TestAMultiLineWarningKeepsItsCauses(t *testing.T) {
484		t.Parallel()
485	
486		got := setupWarningsFrom(bytes.NewBufferString(
487			"warning: memory coordinator could not launch: exec failed\npermission denied\nno such file\n"))
488		if len(got) != 1 {
489			t.Fatalf("expected one warning carrying its causes, got %d: %q", len(got), got)
490		}
491		for _, cause := range []string{"exec failed", "permission denied", "no such file"} {
492			if !strings.Contains(got[0], cause) {
493				t.Errorf("the re-emitted warning lost a cause %q: %s", cause, got[0])
494			}
495		}
496	
497		// A continuation ends at a blank line, so unrelated stderr written after a
498		// warning is not swept into it.
499		sep := setupWarningsFrom(bytes.NewBufferString(
500			"warning: first: a\nb\n\nunrelated progress noise\nwarning: second\n"))
501		if len(sep) != 2 {
502			t.Fatalf("expected two warnings, got %d: %q", len(sep), sep)
503		}
504		if strings.Contains(sep[0], "unrelated progress noise") {
505			t.Errorf("stderr after a blank line was swept into the warning: %s", sep[0])
506		}
507		if sep[1] != "second" {
508			t.Errorf("the second warning was altered: %q", sep[1])
509		}
510	}
