15	// statusFixtureReport is the report the screenshot that started this work came
16	// from, reduced to the shape that matters: forty-four vendored JSON corpora the
17	// semantic provider skipped, reported once as partial failures and AGAIN as
18	// blind spots, plus a relation-type histogram.
19	func statusFixtureReport(t *testing.T, blindSpotCount int) brainStatusReport {
20		t.Helper()
21		now := time.Date(2026, 8, 21, 15, 0, 0, 0, time.UTC)
22		spots := make([]brainBlindSpot, 0, blindSpotCount)
23		warnings := make([]semanticWarning, 0, blindSpotCount)
24		for i := 0; i < blindSpotCount; i++ {
25			path := "benchmarks/agent-brain/mined/entire-cli-" + strconv.Itoa(i) + ".json"
26			spots = append(spots, brainBlindSpot{
27				Path:   path,
28				Code:   "E_MINIFIED",
29				Detail: "file appears minified/bundled (very long lines); not analyzed as source",
30			})
31			warnings = append(warnings, semanticWarning{
32				Code:     "E_MINIFIED",
33				Severity: "warning",
34				Path:     path,
35				Effect:   "file record emitted but symbol parsing skipped",
36				Detail:   "file appears minified/bundled (very long lines); not analyzed as source",
37			})
38		}
39		return brainStatusReport{
40			GeneratedAt: now,
41			Repo:        brainStatusRepo{Root: "/repo", Key: "gh/entireio/entire-brain"},
42			Brain:       brainStatusBrain{Path: "/brain", ManifestState: "current", Schema: 3, SupportedSchema: 3},
43			Sources:     brainStatusSources{Seed: true, Sessions: true, Semantic: true, Docs: true, Facts: true},
44			Facts:       &brainStatusFacts{Facts: 375, Distilled: 375, Branches: 2},
45			Semantic: &brainStatusSemantic{
46				Coverage: &brainStatusSemanticCoverage{
47					Files:                 1179,
48					Symbols:               40781,
49					Relations:             131529,
50					PartialFailures:       blindSpotCount,
51					PartialFailureDetails: warnings,
52					RelationTypes:         []semanticAuditCount{{Name: "CALLS", Count: 34677}, {Name: "DEFINES", Count: 40781}},
53				},
54				BlindSpots: spots,
55				Freshness: &staleReport{Severity: "degraded", Axes: map[string]staleAxis{
56					"semantic_completeness": {State: "degraded", Detail: "44 partial failures"},
57				}},
58			},
59			Onboarding: &brainStatusOnboarding{
60				Facts: factsBackfillStatus{Sessions: 185, Distilled: 20, Running: true, PID: 4242},
61				// Current: the unit on disk IS the one this repo would write. Said
62				// explicitly because it is now load-bearing — a fixture that left it
63				// false would be describing a drifted watcher and would pin the
64				// wrong line as the ordinary case.
65				Daemon:     daemonState{Installed: true, Current: true, Label: "io.entire.brain-watch.a2d3fd66"},
66				LastTickAt: now.Add(-17 * time.Minute),
67				Components: []brainStatusComponent{
