69					{Name: "seed", State: "built"},
70					{Name: "docs", State: "built"},
71					{Name: "semantic", State: "built"},
72					{Name: "history", State: "missing"},
73				},
74			},
75			Live: brainLiveState{Branch: "main", Head: "58b0c54e"},
76		}
