115	// TestShortStatusNeverLeaksTheVerboseWall is the mutation guard named in the
116	// brief: if any part of the full dump escapes into the default view, this
117	// fails. Line count is the honest proxy — the wall was 130 lines.
118	func TestShortStatusNeverLeaksTheVerboseWall(t *testing.T) {
119		t.Parallel()
120		got := renderStatus(t, statusFixtureReport(t, 44), false)
121		if lines := strings.Count(got, "\n"); lines > 16 {
122			t.Fatalf("the default report grew to %d lines; it exists to be short:\n%s", lines, got)
123		}
124		for _, forbidden := range []string{
125			"E_MINIFIED",     // per-file warnings
126			"relation types", // the histogram
127			// The duplicate listing, named by its section header. The verdict is
128			// allowed to say "44 partial failures" as a COUNT on its one cause
129			// line -- that is the collapse working, and the number is why the
130			// reader would open --verbose. What must never appear is the section
131			// that enumerates them, which the path check below also catches.
132			"partial failures:",
133			"benchmarks/agent-brain", // any enumerated path
134			"Retrieval",              // full-report sections
135			"Live",
136			"file languages",
137		} {
138			if strings.Contains(got, forbidden) {
139				t.Errorf("the verbose wall leaked %q into the default report:\n%s", forbidden, got)
140			}
141		}
142	}
