292	// A watcher can be running and still not be YOURS: another repo's `setup`, or an
293	// older build, leaves a unit on disk that is not the one this repo would write.
294	// inspectDaemon computes exactly that (Current), and the status line dropped it,
295	// so the reader saw "running" and had no way to learn the watcher was not theirs.
296	func TestStatusSaysWhenTheInstalledDaemonIsNotCurrent(t *testing.T) {
297		t.Parallel()
298		report := statusFixtureReport(t, 44)
299		report.Onboarding.Daemon = daemonState{
300			Installed: true,
301			Running:   true,
302			Current:   false,
303			Label:     "io.entire.brain-watch.a2d3fd66",
304		}
305		got := renderStatus(t, report, false)
306		if !strings.Contains(got, "not current") {
307			t.Fatalf("a running-but-not-current watcher must say so in status:\n%s", got)
308		}
309		if !strings.Contains(got, "entire-brain setup") {
310			t.Fatalf("status must say what to do about it:\n%s", got)
