324			if !strings.Contains(got, want) {
325				t.Fatalf("next step %q does not name %q", got, want)
326			}
327		}
328		if withProvider := (statusHealth{SemanticMissing: true}).nextStepMessage(base.SetupBrainBinaryName); strings.Contains(withProvider, "plugin install") {
329			t.Fatalf("provider-present next step must stay the refresh remedy: %q", withProvider)
