29	// statusTruthFixture wires an isolated brain over a fake git repo. Nothing is
30	// built: each test below decides how much of a brain to create.
31	//
32	// The live-state git calls are scripted to a clean worktree on purpose. The
33	// verdict under test is a SUM, so an unscripted command would add a warning,
34	// the sum would be nonzero, and the fixture would stop being able to reproduce
35	// the "+ healthy" it exists to pin.
36	func statusTruthFixture(t *testing.T) (Options, string, string) {
37		t.Helper()
38		repoDir := t.TempDir()
39		env := semanticTestEnv(t, repoDir)
40		env.RepoRoot = repoDir
41		runner := semanticFixtureRunner(repoDir, semanticFixtureSnapshot("1.0"))
42		runner.responses[fakeCommandKey("git", "status", "--porcelain", "--untracked-files=all")] = fakeCommandResponse{}
43		runner.responses[fakeCommandKey("git", "diff-index", "-M", "--shortstat", "HEAD")] = fakeCommandResponse{}
44		runner.responses[fakeCommandKey("git", "diff", "--name-status", "-M", "-C", "HEAD")] = fakeCommandResponse{}
45		now := time.Date(2026, 9, 7, 12, 0, 0, 0, time.UTC)
46		opts := Options{Version: "test", Env: env, Runner: runner, Now: func() time.Time { return now }}
47		storage, err := repoStoragePaths(context.Background(), runner, env, repoDir)
48		if err != nil {
49			t.Fatal(err)
50		}
51		return opts, repoDir, storage.BrainDir
