357	// shredSemanticStore overwrites the head of a SQLite file with random bytes,
358	// which is what a torn write or a half-synced copy leaves behind: the file is
359	// still there, still the right size, and no longer a database.
360	func shredSemanticStore(t *testing.T, path string) {
361		t.Helper()
362		file, err := os.OpenFile(path, os.O_WRONLY, 0o600)
363		if err != nil {
364			t.Fatalf("open semantic store: %v", err)
365		}
366		defer file.Close()
367		noise := make([]byte, 200)
368		if _, err := rand.Read(noise); err != nil {
369			t.Fatalf("random bytes: %v", err)
370		}
371		if _, err := file.WriteAt(noise, 0); err != nil {
372			t.Fatalf("shred semantic store: %v", err)
373		}
374	}
