// PlainCaps is the byte-stable mode: whole lines, ASCII, no colour. Every
// non-terminal destination resolves to exactly this, which is what makes the
// plain path safe to assert on in tests and safe to pipe into a log.
func PlainCaps() Caps { return Caps{} }

// EnvLookup is os.LookupEnv's shape. The "found" half matters: NO_COLOR is
// honoured by PRESENCE, so NO_COLOR= (empty) must still disable colour, and a
// plain getenv cannot tell that from unset.
type EnvLookup func(string) (string, bool)

// DetectCaps resolves the capabilities of w from the process environment.
func DetectCaps(w io.Writer) Caps { return DetectCapsWithEnv(w, os.LookupEnv) }

// DetectCapsWithEnv is DetectCaps with the environment injected, so the
// TTY/NO_COLOR/locale matrix is testable without mutating process state.
func DetectCapsWithEnv(w io.Writer, lookup EnvLookup) Caps {
	file, ok := w.(*os.File)
	if !ok || file == nil {
		return PlainCaps()
	}
	fd := file.Fd()
	if !isatty.IsTerminal(fd) && !isatty.IsCygwinTerminal(fd) {
		return PlainCaps()
	}
	caps := terminalCaps(lookup)
	if caps.TTY {
		caps.Width = terminalWidth(fd, func(key string) string { value, _ := lookup(key); return value })
	}
	return caps
}

// terminalCaps resolves environment policy after the caller verifies a terminal.
func terminalCaps(lookup EnvLookup) Caps {
	if lookup == nil {
		lookup = func(string) (string, bool) { return "", false }
	}
	getenv := func(key string) string { value, _ := lookup(key); return value }
	if !SupportsFullScreen(getenv) {
		return PlainCaps()
	}
	caps := Caps{TTY: true, Unicode: localeIsUTF8(getenv)}
	// NO_COLOR is defined by presence, including an empty value.
	if _, noColor := lookup("NO_COLOR"); !noColor {
		caps.Color = true
	}
	return caps
}

// SupportsFullScreen reports whether TERM describes a terminal that can be
// driven with escape sequences at all. TERM=dumb and an unset TERM do not: a
// dumb terminal has no cursor addressing, no alternate screen and no SGR, so
// anything written for one arrives as literal escape bytes.
//
// It gates both halves of this package. The line renderer above drops to
// PlainCaps; the dashboard declines to start and the caller prints the plain
// summary instead — otherwise `dash` on TERM=dumb pushed \x1b[?1049h, a
// rounded-border layout and 256-colour SGR at a terminal that renders every
// byte of it as text.
func SupportsFullScreen(getenv func(string) string) bool {
	if getenv == nil {
		return false
	}
	term := strings.TrimSpace(getenv("TERM"))
	return term != "" && term != "dumb"
}

